"""Internal stream sorting helper."""
import hashlib
from typing import List
from event_packet import EventPacket

def _get_payload_sha256(payload: str) -> str:
    """Computes the SHA-256 digest of a payload string for deterministic ordering."""
    return hashlib.sha256(payload.encode('utf-8')).hexdigest()

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    """
    Orders event packets primarily by severity (descending).
    For packets with identical severity, they are deterministically ordered
    by their payload's SHA-256 digest (ascending lexicographical order)
    as per Rule H07.
    """
    return sorted(packets, key=lambda p: (-p.severity, _get_payload_sha256(p.payload)))

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

def count_critical_packets(packets: List[EventPacket]) -> int:
    return sum(1 for p in packets if p.is_critical())
